using RailwayWebBuilderCore.Enums;

namespace RailwayWebBuilderCore._SiteData.ModelRailways.Layouts;

internal class Kaninchenbau : LayoutBase
{
    public Kaninchenbau()
    {
        Name = LayoutNamesEnums.Kaninchenbau;
        Owner = "";
        Description = "Kaninchenbau is a computer controlled H0e layout modelled on the rolling, grassy meadows typical of the European Alpine region, the hands-off nature of the automation allowing discussions about the layout to continue while it keeps running. It is built using ready-to-run H0e stock from various European manufacturers and is based on the prototype narrow gauge lines seen in Alpine border areas, which theoretically allows rolling stock and locomotives to be lent between operators. The layout has two levels interconnected within the hidden sections, so trains will not always appear from tunnels in the expected order, let alone from the expected tunnel mouth. It is designed to maximise audience interest by always having several trains running simultaneously, usually at least five, and that number of trains plus the complexity of the trackwork means the model had to be automated - achieved using the commercial software iTrain. The program knows the location of every train at all times because the track, just like the real railway, is divided into blocks which can be seen on an iPad, and operation is fully automatic with routes, stopping stations and wait times all chosen randomly by iTrain, which also controls the signals and turnouts. Kaninchenbau is named after the layout style - it literally means Rabbit Warren.";
    }
}